// Módulo 2 — Filtro del catálogo CISA KEV (nodo Code de n8n, modo "Run Once for All Items").
// Copia TODO este archivo dentro del nodo Code. El mismo archivo se prueba en local con:
//   npm test
//
// Entrada ($input):       filas de Oracle del nodo "M4 · Leer inventario" -> { vendor }
// Entrada ($(NODO_KEV)):  el JSON completo de CISA KEV -> { count, vulnerabilities: [...] }
// Salida:        0..N items { cveID, vendor, product, name, description, dateAdded, dueDate, ransomware }

const NODO_KEV = 'M1 · Descargar CISA KEV';

const CONFIG = {
  dias: 2, // ventana de dateAdded. Para probar usa 30.
};

class InventarioVacioError extends Error {
  constructor(mensaje) {
    super(mensaje);
    this.name = 'InventarioVacioError';
  }
}

/**
 * Convierte las filas de la tabla INVENTARIO en la lista de fabricantes.
 * Un inventario vacío se trata como error: casi siempre es una tabla sin datos o un fallo de conexión,
 * y filtrar contra nada dejaría el sistema "funcionando" sin avisar de ninguna vulnerabilidad.
 * @param {Array<Object>} filas  filas { vendor }; las que no traen vendor (p. ej. { success: true }) se ignoran
 * @returns {Array<string>}
 * @throws {InventarioVacioError}
 */
function extraerInventario(filas) {
  const vendors = filas
    .map(f => (f && typeof f.vendor === 'string' ? f.vendor.trim() : ''))
    .filter(v => v !== '');
  if (vendors.length === 0) {
    throw new InventarioVacioError('Leer inventario: la tabla INVENTARIO no tiene fabricantes activos');
  }
  return vendors;
}

/**
 * Devuelve 'YYYY-MM-DD' de hace `dias` días respecto a `ahora`.
 * KEV publica dateAdded como 'YYYY-MM-DD', así que se compara como texto (sin líos de zona horaria).
 */
function fechaDesde(dias, ahora = new Date()) {
  const d = new Date(ahora.getTime() - dias * 24 * 60 * 60 * 1000);
  return d.toISOString().slice(0, 10);
}

function normalizar(texto) {
  return String(texto || '').trim().toLowerCase();
}

/**
 * Filtra el catálogo KEV por fecha e inventario y lo deja en un formato limpio.
 * @param {Array} vulnerabilidades  kev.vulnerabilities
 * @param {Object} opciones         { dias, inventario, ahora }
 */
function filtrarKev(vulnerabilidades, { dias, inventario, ahora } = {}) {
  if (!Array.isArray(vulnerabilidades)) {
    throw new Error('Entrada inválida: se esperaba el arreglo "vulnerabilities" de CISA KEV');
  }
  const desde = fechaDesde(dias, ahora);
  const vendors = new Set(inventario.map(normalizar));

  return vulnerabilidades
    .filter(v => typeof v.dateAdded === 'string' && v.dateAdded >= desde)
    .filter(v => vendors.has(normalizar(v.vendorProject)))
    .map(v => ({
      cveID: v.cveID,
      vendor: v.vendorProject,
      product: v.product,
      name: v.vulnerabilityName,
      description: v.shortDescription,
      dateAdded: v.dateAdded,
      dueDate: v.dueDate,
      ransomware: v.knownRansomwareCampaignUse === 'Known',
    }))
    .sort((a, b) => b.dateAdded.localeCompare(a.dateAdded));
}

// ---- Punto de entrada ----
if (typeof $input !== 'undefined') {
  // Dentro de n8n
  const kev = $(NODO_KEV).first().json;
  const inventario = extraerInventario($input.all().map(item => item.json));
  const relevantes = filtrarKev(kev.vulnerabilities, { ...CONFIG, inventario });
  return relevantes.map(json => ({ json }));
}
// En Node (tests)
module.exports = { filtrarKev, fechaDesde, extraerInventario, InventarioVacioError, CONFIG };

// Módulo 4 — Descartar las vulnerabilidades que ya están en Oracle (nodo Code, modo "Run Once for All Items").
// Va después del nodo Oracle "M4 · CVE ya registrados". Así NVD y la IA solo trabajan con lo nuevo.
//
// Entrada ($input): filas de Oracle { cveID } (o un único { success: true } si la tabla está vacía).
// Entrada ($(NODO_FILTRO)): las vulnerabilidades relevantes que salieron del filtro (M2).
// Salida:  las vulnerabilidades cuyo cveID no está registrado.

const NODO_FILTRO = 'M2 · Filtrar por fecha e inventario';

/**
 * @param {Array<Object>} vulnerabilidades  items del filtro
 * @param {Array<Object>} filas             filas de Oracle; las que no traen cveID (p. ej. { success: true }) se ignoran
 * @returns {Array<Object>}
 */
function descartarRegistrados(vulnerabilidades, filas) {
  const registrados = new Set(
    filas.filter(f => f && typeof f.cveID === 'string').map(f => f.cveID),
  );
  return vulnerabilidades.filter(v => !registrados.has(v.cveID));
}

// ---- Punto de entrada ----
if (typeof $input !== 'undefined') {
  const vulnerabilidades = $(NODO_FILTRO).all().map(item => item.json);
  const filas = $input.all().map(item => item.json);
  return descartarRegistrados(vulnerabilidades, filas).map(json => ({ json }));
}
module.exports = { descartarRegistrados, NODO_FILTRO };

// Módulo 4 — CVSS de NVD y prioridad por reglas (nodo Code, modo "Run Once for All Items").
// Va justo después del nodo HTTP que consulta NVD. Copia TODO este archivo dentro del nodo Code.
//
// Entrada: la respuesta de NVD por cada CVE ({ totalResults, vulnerabilities } o { error }).
// Salida:  la vulnerabilidad + { cvss, severidad, fuenteCvss, motivoSinCvss, prioridad }.
//
// La prioridad la deciden reglas fijas, no la IA: un modelo de 3-4B sobrestimaba la urgencia
// (ver prompts/analista.md). La IA solo redacta el resumen y la acción.

const NODO_ORIGEN = 'M4 · Descartar ya registrados';

// Orden de preferencia de versiones de CVSS presentes en NVD 2.0. Otras métricas (p. ej. ssvcV203) se ignoran.
const VERSIONES_CVSS = ['cvssMetricV31', 'cvssMetricV30', 'cvssMetricV40', 'cvssMetricV2'];

const MOTIVOS_SIN_CVSS = {
  SIN_RESPUESTA: 'sin_respuesta',
  NO_ENCONTRADO: 'no_encontrado',
  SIN_METRICAS: 'sin_metricas',
};

const UMBRALES = { alta: 9, media: 7 };

/**
 * @typedef {'alta'|'media'|'baja'|'revisar'} Prioridad
 * @typedef {{ok: true, cvss: number, severidad: string|null, fuente: string}
 *         | {ok: false, motivo: string, detalle: string}} ResultadoCvss
 */

function puntajeValido(valor) {
  return typeof valor === 'number' && Number.isFinite(valor) && valor >= 0 && valor <= 10;
}

/** Primary (NIST) primero; si no hay, Secondary (el fabricante), que es lo habitual en CVE recientes. */
function mejorMetrica(metricas) {
  const validas = metricas.filter(m => m && m.cvssData && puntajeValido(m.cvssData.baseScore));
  return validas.find(m => m.type === 'Primary') || validas[0] || null;
}

/**
 * @param {Object} respuestaNvd  json del nodo HTTP de NVD
 * @returns {ResultadoCvss}
 */
/**
 * Describe una respuesta inesperada de NVD. Según la versión de n8n, el error del nodo HTTP llega
 * como texto ({ error: '...' }) o como objeto ({ error: { message, httpCode } }).
 */
function describirRespuesta(respuesta) {
  if (!respuesta || typeof respuesta !== 'object') return `respuesta vacía (${JSON.stringify(respuesta)})`;
  const { error } = respuesta;
  if (typeof error === 'string' && error !== '') return error;
  if (error && typeof error === 'object') {
    // code: errores de Node antes de enviar la solicitud (p. ej. ERR_INVALID_HTTP_TOKEN = nombre de header inválido)
    const partes = [error.httpCode, error.code, error.message, error.description].filter(p => p !== undefined && p !== '');
    if (partes.length > 0) return partes.join(' - ');
    // Formato desconocido: se muestra tal cual (recortado) para poder diagnosticarlo en n8n
    return `error sin mensaje conocido: ${JSON.stringify(error).slice(0, 300)}`;
  }
  if (error !== undefined) return `error sin mensaje: ${JSON.stringify(error)}`;
  return `la respuesta no trae "vulnerabilities"; claves recibidas: ${Object.keys(respuesta).slice(0, 8).join(', ') || 'ninguna'}`;
}

function extraerCvss(respuestaNvd) {
  if (!respuestaNvd || !Array.isArray(respuestaNvd.vulnerabilities)) {
    return { ok: false, motivo: MOTIVOS_SIN_CVSS.SIN_RESPUESTA, detalle: describirRespuesta(respuestaNvd) };
  }
  const cve = respuestaNvd.vulnerabilities[0] && respuestaNvd.vulnerabilities[0].cve;
  if (!cve) {
    return { ok: false, motivo: MOTIVOS_SIN_CVSS.NO_ENCONTRADO, detalle: 'NVD no tiene registro del CVE' };
  }

  const metricas = cve.metrics || {};
  for (const version of VERSIONES_CVSS) {
    const elegida = Array.isArray(metricas[version]) ? mejorMetrica(metricas[version]) : null;
    if (elegida) {
      const severidad = elegida.cvssData.baseSeverity || elegida.baseSeverity || null;
      return { ok: true, cvss: elegida.cvssData.baseScore, severidad, fuente: `${version}/${elegida.type || 's/d'}` };
    }
  }
  return { ok: false, motivo: MOTIVOS_SIN_CVSS.SIN_METRICAS, detalle: 'NVD aún no publica un puntaje CVSS' };
}

/**
 * Reglas: ransomware o CVSS >= 9 -> alta; 7 a 8.9 -> media; < 7 -> baja; sin CVSS -> revisar.
 * @param {{ransomware: boolean, cvss: number|null}} datos
 * @returns {Prioridad}
 */
function calcularPrioridad({ ransomware, cvss }) {
  if (ransomware === true) return 'alta';
  if (cvss === null) return 'revisar';
  if (cvss >= UMBRALES.alta) return 'alta';
  if (cvss >= UMBRALES.media) return 'media';
  return 'baja';
}

/**
 * @param {Object} vulnerabilidad  item del filtro (M2) ya sin los registrados
 * @param {Object} respuestaNvd
 */
function enriquecerConNvd(vulnerabilidad, respuestaNvd) {
  const resultado = extraerCvss(respuestaNvd);
  const cvss = resultado.ok ? resultado.cvss : null;
  return {
    ...vulnerabilidad,
    cvss,
    severidad: resultado.ok ? resultado.severidad : null,
    fuenteCvss: resultado.ok ? resultado.fuente : null,
    motivoSinCvss: resultado.ok ? null : `${resultado.motivo}: ${resultado.detalle}`,
    prioridad: calcularPrioridad({ ransomware: vulnerabilidad.ransomware, cvss }),
  };
}

// ---- Punto de entrada ----
if (typeof $input !== 'undefined') {
  // El nodo HTTP reemplaza el item por la respuesta de NVD; la vulnerabilidad se recupera del nodo anterior.
  return $input.all().map((item, i) => ({
    json: enriquecerConNvd($(NODO_ORIGEN).itemMatching(i).json, item.json),
  }));
}
module.exports = { extraerCvss, calcularPrioridad, enriquecerConNvd, MOTIVOS_SIN_CVSS, NODO_ORIGEN };

// Módulo 3 — Preparar la solicitud al Analista IA (nodo Code, modo "Run Once for All Items").
// Se usa en dos nodos: "M3 · Preparar solicitud" (intento 1) y "M3 · Preparar reintento" (intento 2).
// Copia TODO este archivo dentro del nodo Code. Se prueba en local con: npm test
//
// Entrada: items con CVSS y prioridad (M4 · Calcular CVSS y prioridad) o items del validador con reintentar = true.
// Salida:  el mismo item limpio + { intento, solicitudOllama } listo para el nodo HTTP de Ollama.

const CONFIG = {
  modelo: 'phi4-mini',
  // temperature 0: la misma vulnerabilidad debe producir la misma clasificación
  opciones: { temperature: 0 },
};

// Campos de control que agrega este módulo o el validador; no son datos de la vulnerabilidad.
const CAMPOS_CONTROL = ['intento', 'reintentar', 'motivoFallo', 'detalleFallo', 'solicitudOllama'];

class EntradaInvalidaError extends Error {
  constructor(mensaje) {
    super(mensaje);
    this.name = 'EntradaInvalidaError';
  }
}

/**
 * @typedef {Object} Vulnerabilidad
 * @property {string} cveID
 * @property {string} vendor
 * @property {string} product
 * @property {string} name
 * @property {string} description
 * @property {string} dueDate          'YYYY-MM-DD'
 * @property {boolean} ransomware
 * @property {number|null} cvss       de NVD; null si aún no tiene puntaje
 * @property {'alta'|'media'|'baja'|'revisar'} prioridad  decidida por reglas
 */

/** Separa los datos de la vulnerabilidad de los campos de control. */
function datosVulnerabilidad(item) {
  return Object.fromEntries(Object.entries(item).filter(([k]) => !CAMPOS_CONTROL.includes(k)));
}

/** Solo los datos que el modelo necesita: menos texto = respuesta más rápida en CPU. */
function datosParaPrompt(v) {
  const datos = {
    cve: v.cveID,
    fabricante: v.vendor,
    producto: v.product,
    nombre: v.name,
    descripcion: v.description,
    usada_en_ransomware: v.ransomware,
    fecha_limite_cisa: v.dueDate,
  };
  const conCvss = typeof v.cvss === 'number' ? { ...datos, cvss: v.cvss } : datos;
  return { ...conCvss, prioridad: v.prioridad };
}

// La prioridad ya viene decidida por reglas (04_cvss_prioridad.js); el modelo solo redacta.
// Se le entrega para que la urgencia de la acción sea coherente con ella.
function construirPrompt(v) {
  return [
    'Eres un analista de ciberseguridad que asesora al único encargado de sistemas de una clínica pequeña.',
    'Con los datos de la vulnerabilidad, responde SOLO un objeto JSON con exactamente estas claves:',
    '- "resumen": máximo 2 frases en español, explicando qué permite hacer a un atacante.',
    '- "accion": 1 frase completa en español, con un verbo y el nombre del producto, que diga qué hacer y cuándo.',
    // Con la lista de urgencias como palabras sueltas, phi4-mini respondía accion = "revisar" (probado 17-nov-2026)
    'La prioridad ya está decidida; no la cambies ni la menciones. Según la prioridad, el plazo de la acción es:',
    'alta -> hoy mismo; media -> durante esta semana; baja -> en el próximo ciclo de actualizaciones;',
    'revisar -> primero confirmar si el producto está instalado y expuesto a Internet.',
    'Ejemplo de accion (otro producto): "Aplicar durante esta semana el parche de seguridad de Apache Tomcat publicado por el fabricante."',
    'No inventes versiones, parches ni impactos que no estén en los datos.',
    `Datos: ${JSON.stringify(datosParaPrompt(v))}`,
  ].join('\n');
}

/**
 * @param {Object} item  item de entrada (vulnerabilidad, con o sin campos de control)
 * @returns {Object}     vulnerabilidad + { intento, solicitudOllama }
 * @throws {EntradaInvalidaError}
 */
function prepararSolicitud(item, config = CONFIG) {
  if (!item || typeof item.cveID !== 'string' || item.cveID === '') {
    throw new EntradaInvalidaError('Preparar solicitud: el item no tiene un cveID válido');
  }
  const intentoPrevio = Number.isInteger(item.intento) ? item.intento : 0;
  const vulnerabilidad = datosVulnerabilidad(item);

  return {
    ...vulnerabilidad,
    intento: intentoPrevio + 1,
    solicitudOllama: {
      model: config.modelo,
      stream: false,
      format: 'json',
      prompt: construirPrompt(vulnerabilidad),
      options: config.opciones,
    },
  };
}

// ---- Punto de entrada ----
if (typeof $input !== 'undefined') {
  return $input.all().map(item => ({ json: prepararSolicitud(item.json) }));
}
module.exports = { prepararSolicitud, construirPrompt, datosVulnerabilidad, EntradaInvalidaError, CONFIG, CAMPOS_CONTROL };

// Módulo 3 — Validar la respuesta del Analista IA (nodo Code, modo "Run Once for All Items").
// Se usa en dos nodos: "M3 · Validar análisis" (intento 1) y "M3 · Validar reintento" (intento 2).
// Copia TODO este archivo dentro del nodo Code y ajusta NODO_SOLICITUD al nombre del nodo
// "Preparar ..." que va justo antes del HTTP de Ollama (scripts/construir_workflow.js lo hace solo).
//
// Entrada: la respuesta del nodo HTTP de Ollama ({ response: "<texto JSON>" } o { error: "..." }).
// Salida:  la vulnerabilidad (con su prioridad por reglas intacta) + una de estas tres formas:
//   - válida:     { resumen, accion, reintentar: false }
//   - reintentar: { reintentar: true, motivoFallo, detalleFallo }                   (si quedan intentos)
//   - sin texto:  { resumen: null, accion: null, reintentar: false, motivoFallo, detalleFallo }
// Que la IA falle no cambia la prioridad: una vulnerabilidad "alta" debe avisarse aunque no haya resumen.

const NODO_SOLICITUD = 'M3 · Preparar solicitud';
const MAX_INTENTOS = 2;
// Coinciden con las columnas resumen_es VARCHAR2(1000) y accion VARCHAR2(500) de Oracle (v4)
const LIMITES = { resumen: 1000, accion: 500 };

const MOTIVOS = {
  SIN_RESPUESTA: 'sin_respuesta',
  JSON_INVALIDO: 'json_invalido',
  CAMPO_FALTANTE: 'campo_faltante',
  CAMPO_MUY_LARGO: 'campo_muy_largo',
  ACCION_INCOMPLETA: 'accion_incompleta',
};

// Una acción de 1-2 palabras (p. ej. "revisar", visto con phi4-mini) no es ejecutable por el encargado.
const MIN_PALABRAS_ACCION = 3;

// Duplicado de 03_preparar_solicitud.js: cada nodo Code de n8n es independiente y no puede importar otro.
const CAMPOS_CONTROL = ['intento', 'reintentar', 'motivoFallo', 'detalleFallo', 'solicitudOllama'];

class EntradaInvalidaError extends Error {
  constructor(mensaje) {
    super(mensaje);
    this.name = 'EntradaInvalidaError';
  }
}

function datosVulnerabilidad(item) {
  return Object.fromEntries(Object.entries(item).filter(([k]) => !CAMPOS_CONTROL.includes(k)));
}

function fallo(motivo, detalle) {
  return { ok: false, motivo, detalle };
}

function textoLimpio(valor) {
  return typeof valor === 'string' ? valor.trim() : '';
}

/**
 * Interpreta la respuesta cruda de Ollama.
 * @param {Object} respuestaOllama  json del nodo HTTP: { response: string } o { error: string }
 * @returns {{ok: true, analisis: {resumen: string, accion: string}}
 *         | {ok: false, motivo: string, detalle: string}}
 */
function interpretarRespuesta(respuestaOllama) {
  if (!respuestaOllama || typeof respuestaOllama.response !== 'string') {
    const detalle = textoLimpio(respuestaOllama && respuestaOllama.error) || 'la respuesta no trae el campo "response"';
    return fallo(MOTIVOS.SIN_RESPUESTA, detalle);
  }

  let datos;
  try {
    datos = JSON.parse(respuestaOllama.response);
  } catch (error) {
    return fallo(MOTIVOS.JSON_INVALIDO, error.message);
  }
  if (datos === null || typeof datos !== 'object' || Array.isArray(datos)) {
    return fallo(MOTIVOS.JSON_INVALIDO, 'se esperaba un objeto JSON');
  }

  const resumen = textoLimpio(datos.resumen);
  const accion = textoLimpio(datos.accion);
  if (resumen === '' || accion === '') {
    return fallo(MOTIVOS.CAMPO_FALTANTE, 'faltan "resumen" o "accion"');
  }
  if (resumen.length > LIMITES.resumen || accion.length > LIMITES.accion) {
    return fallo(MOTIVOS.CAMPO_MUY_LARGO, `resumen ${resumen.length}/${LIMITES.resumen}, accion ${accion.length}/${LIMITES.accion}`);
  }
  const palabras = accion.split(/\s+/).length;
  if (palabras < MIN_PALABRAS_ACCION) {
    return fallo(MOTIVOS.ACCION_INCOMPLETA, `accion con ${palabras} palabra(s): ${JSON.stringify(accion)}`);
  }

  return { ok: true, analisis: { resumen, accion } };
}

/**
 * Decide el resultado final del item: análisis válido, reintento o sin texto de la IA.
 * @param {Object} solicitud        item que salió del nodo "Preparar ..." (vulnerabilidad + intento)
 * @param {Object} respuestaOllama  item que salió del nodo HTTP de Ollama
 * @throws {EntradaInvalidaError}
 */
function resolverAnalisis(solicitud, respuestaOllama, maxIntentos = MAX_INTENTOS) {
  if (!solicitud || typeof solicitud.cveID !== 'string' || !Number.isInteger(solicitud.intento)) {
    throw new EntradaInvalidaError('Validar análisis: la solicitud original no tiene cveID o intento');
  }
  const vulnerabilidad = datosVulnerabilidad(solicitud);
  const { intento } = solicitud;
  const resultado = interpretarRespuesta(respuestaOllama);

  if (resultado.ok) {
    return { ...vulnerabilidad, ...resultado.analisis, intento, reintentar: false };
  }
  const diagnostico = { motivoFallo: resultado.motivo, detalleFallo: resultado.detalle };
  if (intento < maxIntentos) {
    return { ...vulnerabilidad, intento, reintentar: true, ...diagnostico };
  }
  return { ...vulnerabilidad, intento, reintentar: false, resumen: null, accion: null, ...diagnostico };
}

// ---- Punto de entrada ----
if (typeof $input !== 'undefined') {
  // El nodo HTTP reemplaza el item por la respuesta; la vulnerabilidad se recupera del nodo que preparó la solicitud.
  return $input.all().map((item, i) => ({
    json: resolverAnalisis($(NODO_SOLICITUD).itemMatching(i).json, item.json),
  }));
}
module.exports = { resolverAnalisis, interpretarRespuesta, EntradaInvalidaError, MOTIVOS, MAX_INTENTOS, NODO_SOLICITUD };

// Módulo 3 — Preparar la solicitud al Analista IA (nodo Code, modo "Run Once for All Items").
// Se usa en dos nodos: "M3 · Preparar solicitud" (intento 1) y "M3 · Preparar reintento" (intento 2).
// Copia TODO este archivo dentro del nodo Code. Se prueba en local con: npm test
//
// Entrada: items con CVSS y prioridad (M4 · Calcular CVSS y prioridad) o items del validador con reintentar = true.
// Salida:  el mismo item limpio + { intento, solicitudOllama } listo para el nodo HTTP de Ollama.

const CONFIG = {
  modelo: 'phi4-mini',
  // temperature 0: la misma vulnerabilidad debe producir la misma clasificación
  opciones: { temperature: 0 },
};

// Campos de control que agrega este módulo o el validador; no son datos de la vulnerabilidad.
const CAMPOS_CONTROL = ['intento', 'reintentar', 'motivoFallo', 'detalleFallo', 'solicitudOllama'];

class EntradaInvalidaError extends Error {
  constructor(mensaje) {
    super(mensaje);
    this.name = 'EntradaInvalidaError';
  }
}

/**
 * @typedef {Object} Vulnerabilidad
 * @property {string} cveID
 * @property {string} vendor
 * @property {string} product
 * @property {string} name
 * @property {string} description
 * @property {string} dueDate          'YYYY-MM-DD'
 * @property {boolean} ransomware
 * @property {number|null} cvss       de NVD; null si aún no tiene puntaje
 * @property {'alta'|'media'|'baja'|'revisar'} prioridad  decidida por reglas
 */

/** Separa los datos de la vulnerabilidad de los campos de control. */
function datosVulnerabilidad(item) {
  return Object.fromEntries(Object.entries(item).filter(([k]) => !CAMPOS_CONTROL.includes(k)));
}

/** Solo los datos que el modelo necesita: menos texto = respuesta más rápida en CPU. */
function datosParaPrompt(v) {
  const datos = {
    cve: v.cveID,
    fabricante: v.vendor,
    producto: v.product,
    nombre: v.name,
    descripcion: v.description,
    usada_en_ransomware: v.ransomware,
    fecha_limite_cisa: v.dueDate,
  };
  const conCvss = typeof v.cvss === 'number' ? { ...datos, cvss: v.cvss } : datos;
  return { ...conCvss, prioridad: v.prioridad };
}

// La prioridad ya viene decidida por reglas (04_cvss_prioridad.js); el modelo solo redacta.
// Se le entrega para que la urgencia de la acción sea coherente con ella.
function construirPrompt(v) {
  return [
    'Eres un analista de ciberseguridad que asesora al único encargado de sistemas de una clínica pequeña.',
    'Con los datos de la vulnerabilidad, responde SOLO un objeto JSON con exactamente estas claves:',
    '- "resumen": máximo 2 frases en español, explicando qué permite hacer a un atacante.',
    '- "accion": 1 frase completa en español, con un verbo y el nombre del producto, que diga qué hacer y cuándo.',
    // Con la lista de urgencias como palabras sueltas, phi4-mini respondía accion = "revisar" (probado 17-nov-2026)
    'La prioridad ya está decidida; no la cambies ni la menciones. Según la prioridad, el plazo de la acción es:',
    'alta -> hoy mismo; media -> durante esta semana; baja -> en el próximo ciclo de actualizaciones;',
    'revisar -> primero confirmar si el producto está instalado y expuesto a Internet.',
    'Ejemplo de accion (otro producto): "Aplicar durante esta semana el parche de seguridad de Apache Tomcat publicado por el fabricante."',
    'No inventes versiones, parches ni impactos que no estén en los datos.',
    `Datos: ${JSON.stringify(datosParaPrompt(v))}`,
  ].join('\n');
}

/**
 * @param {Object} item  item de entrada (vulnerabilidad, con o sin campos de control)
 * @returns {Object}     vulnerabilidad + { intento, solicitudOllama }
 * @throws {EntradaInvalidaError}
 */
function prepararSolicitud(item, config = CONFIG) {
  if (!item || typeof item.cveID !== 'string' || item.cveID === '') {
    throw new EntradaInvalidaError('Preparar solicitud: el item no tiene un cveID válido');
  }
  const intentoPrevio = Number.isInteger(item.intento) ? item.intento : 0;
  const vulnerabilidad = datosVulnerabilidad(item);

  return {
    ...vulnerabilidad,
    intento: intentoPrevio + 1,
    solicitudOllama: {
      model: config.modelo,
      stream: false,
      format: 'json',
      prompt: construirPrompt(vulnerabilidad),
      options: config.opciones,
    },
  };
}

// ---- Punto de entrada ----
if (typeof $input !== 'undefined') {
  return $input.all().map(item => ({ json: prepararSolicitud(item.json) }));
}
module.exports = { prepararSolicitud, construirPrompt, datosVulnerabilidad, EntradaInvalidaError, CONFIG, CAMPOS_CONTROL };

// Módulo 3 — Validar la respuesta del Analista IA (nodo Code, modo "Run Once for All Items").
// Se usa en dos nodos: "M3 · Validar análisis" (intento 1) y "M3 · Validar reintento" (intento 2).
// Copia TODO este archivo dentro del nodo Code y ajusta NODO_SOLICITUD al nombre del nodo
// "Preparar ..." que va justo antes del HTTP de Ollama (scripts/construir_workflow.js lo hace solo).
//
// Entrada: la respuesta del nodo HTTP de Ollama ({ response: "<texto JSON>" } o { error: "..." }).
// Salida:  la vulnerabilidad (con su prioridad por reglas intacta) + una de estas tres formas:
//   - válida:     { resumen, accion, reintentar: false }
//   - reintentar: { reintentar: true, motivoFallo, detalleFallo }                   (si quedan intentos)
//   - sin texto:  { resumen: null, accion: null, reintentar: false, motivoFallo, detalleFallo }
// Que la IA falle no cambia la prioridad: una vulnerabilidad "alta" debe avisarse aunque no haya resumen.

const NODO_SOLICITUD = 'M3 · Preparar reintento';
const MAX_INTENTOS = 2;
// Coinciden con las columnas resumen_es VARCHAR2(1000) y accion VARCHAR2(500) de Oracle (v4)
const LIMITES = { resumen: 1000, accion: 500 };

const MOTIVOS = {
  SIN_RESPUESTA: 'sin_respuesta',
  JSON_INVALIDO: 'json_invalido',
  CAMPO_FALTANTE: 'campo_faltante',
  CAMPO_MUY_LARGO: 'campo_muy_largo',
  ACCION_INCOMPLETA: 'accion_incompleta',
};

// Una acción de 1-2 palabras (p. ej. "revisar", visto con phi4-mini) no es ejecutable por el encargado.
const MIN_PALABRAS_ACCION = 3;

// Duplicado de 03_preparar_solicitud.js: cada nodo Code de n8n es independiente y no puede importar otro.
const CAMPOS_CONTROL = ['intento', 'reintentar', 'motivoFallo', 'detalleFallo', 'solicitudOllama'];

class EntradaInvalidaError extends Error {
  constructor(mensaje) {
    super(mensaje);
    this.name = 'EntradaInvalidaError';
  }
}

function datosVulnerabilidad(item) {
  return Object.fromEntries(Object.entries(item).filter(([k]) => !CAMPOS_CONTROL.includes(k)));
}

function fallo(motivo, detalle) {
  return { ok: false, motivo, detalle };
}

function textoLimpio(valor) {
  return typeof valor === 'string' ? valor.trim() : '';
}

/**
 * Interpreta la respuesta cruda de Ollama.
 * @param {Object} respuestaOllama  json del nodo HTTP: { response: string } o { error: string }
 * @returns {{ok: true, analisis: {resumen: string, accion: string}}
 *         | {ok: false, motivo: string, detalle: string}}
 */
function interpretarRespuesta(respuestaOllama) {
  if (!respuestaOllama || typeof respuestaOllama.response !== 'string') {
    const detalle = textoLimpio(respuestaOllama && respuestaOllama.error) || 'la respuesta no trae el campo "response"';
    return fallo(MOTIVOS.SIN_RESPUESTA, detalle);
  }

  let datos;
  try {
    datos = JSON.parse(respuestaOllama.response);
  } catch (error) {
    return fallo(MOTIVOS.JSON_INVALIDO, error.message);
  }
  if (datos === null || typeof datos !== 'object' || Array.isArray(datos)) {
    return fallo(MOTIVOS.JSON_INVALIDO, 'se esperaba un objeto JSON');
  }

  const resumen = textoLimpio(datos.resumen);
  const accion = textoLimpio(datos.accion);
  if (resumen === '' || accion === '') {
    return fallo(MOTIVOS.CAMPO_FALTANTE, 'faltan "resumen" o "accion"');
  }
  if (resumen.length > LIMITES.resumen || accion.length > LIMITES.accion) {
    return fallo(MOTIVOS.CAMPO_MUY_LARGO, `resumen ${resumen.length}/${LIMITES.resumen}, accion ${accion.length}/${LIMITES.accion}`);
  }
  const palabras = accion.split(/\s+/).length;
  if (palabras < MIN_PALABRAS_ACCION) {
    return fallo(MOTIVOS.ACCION_INCOMPLETA, `accion con ${palabras} palabra(s): ${JSON.stringify(accion)}`);
  }

  return { ok: true, analisis: { resumen, accion } };
}

/**
 * Decide el resultado final del item: análisis válido, reintento o sin texto de la IA.
 * @param {Object} solicitud        item que salió del nodo "Preparar ..." (vulnerabilidad + intento)
 * @param {Object} respuestaOllama  item que salió del nodo HTTP de Ollama
 * @throws {EntradaInvalidaError}
 */
function resolverAnalisis(solicitud, respuestaOllama, maxIntentos = MAX_INTENTOS) {
  if (!solicitud || typeof solicitud.cveID !== 'string' || !Number.isInteger(solicitud.intento)) {
    throw new EntradaInvalidaError('Validar análisis: la solicitud original no tiene cveID o intento');
  }
  const vulnerabilidad = datosVulnerabilidad(solicitud);
  const { intento } = solicitud;
  const resultado = interpretarRespuesta(respuestaOllama);

  if (resultado.ok) {
    return { ...vulnerabilidad, ...resultado.analisis, intento, reintentar: false };
  }
  const diagnostico = { motivoFallo: resultado.motivo, detalleFallo: resultado.detalle };
  if (intento < maxIntentos) {
    return { ...vulnerabilidad, intento, reintentar: true, ...diagnostico };
  }
  return { ...vulnerabilidad, intento, reintentar: false, resumen: null, accion: null, ...diagnostico };
}

// ---- Punto de entrada ----
if (typeof $input !== 'undefined') {
  // El nodo HTTP reemplaza el item por la respuesta; la vulnerabilidad se recupera del nodo que preparó la solicitud.
  return $input.all().map((item, i) => ({
    json: resolverAnalisis($(NODO_SOLICITUD).itemMatching(i).json, item.json),
  }));
}
module.exports = { resolverAnalisis, interpretarRespuesta, EntradaInvalidaError, MOTIVOS, MAX_INTENTOS, NODO_SOLICITUD };

// Módulo 4 — Preparar el registro para Oracle (nodo Code, modo "Run Once for All Items").
// Convierte la vulnerabilidad analizada en los valores que usa el MERGE de "M4 · Guardar en Oracle".
//
// Entrada: la vulnerabilidad después del Analista IA (válida o con resumen/accion null).
// Salida:  { registro: { cve_id, vendor, ..., accion } } con todos los valores como texto;
//          '' representa NULL (Oracle trata la cadena vacía como NULL).

// Tamaños (en bytes) de las columnas de sql/01_tablas.sql
const LIMITES = { vendor: 100, product: 150, nombre: 400, descripcion: 4000, severidad: 20, resumen_es: 1000, accion: 500 };
const PRIORIDADES = ['alta', 'media', 'baja', 'revisar'];
const FECHA = /^\d{4}-\d{2}-\d{2}$/;

class RegistroInvalidoError extends Error {
  constructor(mensaje) {
    super(mensaje);
    this.name = 'RegistroInvalidoError';
  }
}

const SUSPENSIVOS = '...';

function bytesUtf8(caracter) {
  const cp = caracter.codePointAt(0);
  if (cp < 0x80) return 1;
  if (cp < 0x800) return 2;
  if (cp < 0x10000) return 3;
  return 4;
}

/**
 * Recorta al tamaño de la columna para que un texto largo no tumbe el guardado (ORA-12899).
 * Cuenta bytes UTF-8, no caracteres: VARCHAR2(n) en Oracle XE mide en bytes y "á" ocupa 2.
 */
function ajustar(valor, limiteBytes) {
  if (valor === null || valor === undefined) return '';
  const caracteres = Array.from(String(valor));
  const total = caracteres.reduce((suma, c) => suma + bytesUtf8(c), 0);
  if (total <= limiteBytes) return caracteres.join('');

  const disponible = limiteBytes - SUSPENSIVOS.length;
  let usados = 0;
  let corte = 0;
  while (corte < caracteres.length && usados + bytesUtf8(caracteres[corte]) <= disponible) {
    usados += bytesUtf8(caracteres[corte]);
    corte += 1;
  }
  return caracteres.slice(0, corte).join('') + SUSPENSIVOS;
}

/**
 * @param {Object} v  vulnerabilidad analizada
 * @returns {Object}  valores para los parámetros del MERGE
 * @throws {RegistroInvalidoError}  si faltan datos que la tabla exige con formato fijo
 */
function aRegistroOracle(v) {
  const cve = v && v.cveID;
  if (typeof cve !== 'string' || cve === '' || cve.length > 20) {
    throw new RegistroInvalidoError(`Preparar registro: cveID inválido (${JSON.stringify(cve)})`);
  }
  if (!FECHA.test(v.dateAdded) || !FECHA.test(v.dueDate)) {
    throw new RegistroInvalidoError(`Preparar registro ${cve}: dateAdded/dueDate deben ser YYYY-MM-DD`);
  }
  if (!PRIORIDADES.includes(v.prioridad)) {
    throw new RegistroInvalidoError(`Preparar registro ${cve}: prioridad inválida (${JSON.stringify(v.prioridad)})`);
  }
  if (v.cvss !== null && (typeof v.cvss !== 'number' || v.cvss < 0 || v.cvss > 10)) {
    throw new RegistroInvalidoError(`Preparar registro ${cve}: cvss fuera de rango (${JSON.stringify(v.cvss)})`);
  }

  return {
    cve_id: cve,
    vendor: ajustar(v.vendor, LIMITES.vendor),
    product: ajustar(v.product, LIMITES.product),
    nombre: ajustar(v.name, LIMITES.nombre),
    descripcion: ajustar(v.description, LIMITES.descripcion),
    fecha_kev: v.dateAdded,
    fecha_limite: v.dueDate,
    ransomware: v.ransomware === true ? 'S' : 'N',
    // Punto decimal fijo: el MERGE lo convierte con TO_NUMBER(..., NLS_NUMERIC_CHARACTERS = '.,')
    cvss: v.cvss === null ? '' : v.cvss.toFixed(1),
    severidad: ajustar(v.severidad, LIMITES.severidad),
    resumen_es: ajustar(v.resumen, LIMITES.resumen_es),
    prioridad: v.prioridad,
    accion: ajustar(v.accion, LIMITES.accion),
  };
}

// ---- Punto de entrada ----
if (typeof $input !== 'undefined') {
  return $input.all().map(item => ({ json: { ...item.json, registro: aRegistroOracle(item.json) } }));
}
module.exports = { aRegistroOracle, ajustar, RegistroInvalidoError, LIMITES };

// Módulo 5 — Formato del mensaje de Telegram (nodo Code, modo "Run Once for All Items").
// v4: la entrada son las filas pendientes de Oracle (nodo "M5 · Pendientes de notificar").
// Si la IA no produjo resumen o acción, el mensaje usa la descripción de CISA y una acción genérica.
// El nodo Telegram debe enviar el campo {{ $json.mensaje }} como texto plano (sin parse mode).

const ICONOS = { alta: '🔴', media: '🟠', baja: '🟢', revisar: '⚪' };

function formatearMensaje(v) {
  const prioridad = v.prioridad || 'revisar';
  const icono = ICONOS[prioridad] || ICONOS.revisar;
  const cvss = v.cvss != null ? `CVSS ${v.cvss}` : 'CVSS s/d';
  const ransomware = v.ransomware ? 'sí' : 'no';

  return [
    `${icono} PRIORIDAD ${prioridad.toUpperCase()} — ${v.cveID}`,
    `Producto: ${v.vendor} ${v.product}  |  ${cvss}  |  Ransomware: ${ransomware}`,
    `Qué pasa: ${v.resumen || v.description}`,
    `Qué hacer: ${v.accion || 'Revisar el boletín del fabricante y aplicar la actualización.'}`,
    `Fecha límite CISA: ${v.dueDate}`,
  ].join('\n');
}

/**
 * Convierte una fila de Oracle (alias de sql/02_consultas.sql) al formato que usa formatearMensaje.
 * @param {Object} fila  { cveID, vendor, product, description, dueDate, ransomware: 'S'|'N', cvss, resumen, prioridad, accion }
 * @returns {Object|null}  null si la fila no es una vulnerabilidad (p. ej. { success: true } cuando no hay pendientes)
 */
function filaOracleAVulnerabilidad(fila) {
  if (!fila || typeof fila.cveID !== 'string') return null;
  return { ...fila, ransomware: fila.ransomware === 'S' };
}

// ---- Punto de entrada ----
if (typeof $input !== 'undefined') {
  return $input.all()
    .map(item => filaOracleAVulnerabilidad(item.json))
    .filter(v => v !== null)
    .map(v => ({ json: { ...v, mensaje: formatearMensaje(v) } }));
}
module.exports = { formatearMensaje, filaOracleAVulnerabilidad };
